urlset:
{{- range (where .Data.Pages "Section" "!=" "gallery") -}}
    {{- /* Fuera las paginas de etiqueta que solo agrupan un post.        */ -}}
    {{- /* Eran 32 de 35, o sea 32 de las 50 URLs del sitemap: paginas    */ -}}
    {{- /* que solo repiten el titulo y el resumen de UN articulo. Eso es */ -}}
    {{- /* contenido pobre: gasta presupuesto de rastreo y da la          */ -}}
    {{- /* impresion de un sitio lleno de paginas vacias.                 */ -}}
    {{- /* El umbral es automatico: en cuanto una etiqueta llegue a dos   */ -}}
    {{- /* articulos vuelve a entrar sola.                                */ -}}
    {{- $incluir := true -}}
    {{- if and (eq .Kind "term") (eq .Data.Singular "tag") -}}
        {{- if lt (len .Pages) 2 -}}
            {{- $incluir = false -}}
        {{- end -}}
    {{- end -}}
    {{- if $incluir -}}


            {{- .Permalink -}}

        {{- if not .Lastmod.IsZero -}}

                {{- .Lastmod.Format "2006-01-02T15:04:05-07:00" -}}

        {{- end -}}
        {{- with .Sitemap.ChangeFreq -}}

                {{- . -}}

        {{- end -}}

        {{- if ge .Sitemap.Priority 0.0 -}}
            {{- $weeks := div (sub now.Unix .Lastmod.Unix) 604800 -}}
            {{- $priority := sub 1 (div $weeks 10.0 ) -}}
            {{- if ge .Sitemap.Priority $priority -}}
                {{ .Sitemap.Priority }}
            {{- else -}}
                {{ $priority }}
            {{- end -}}
        {{- end -}}

        {{- if .IsTranslated -}}
            {{- range .Translations -}}

            {{- end -}}

        {{- end -}}

    {{- end -}}
{{- end -}}
